package com.foodordering.notification; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="notifications") public class Notification {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; Long orderId; Long customerId; String message; LocalDateTime sentAt; static Notification make(Long o,Long c,String m){Notification n=new Notification();n.orderId=o;n.customerId=c;n.message=m;n.sentAt=LocalDateTime.now();return n;}}
